
.favor-strip {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 6px 12px;
  background: var(--c-cloud);
  border-bottom: 1px dashed var(--c-gold);
  flex-wrap: wrap;
}

.favor-label {
  font-weight: bold;
  font-size: 0.88rem;
  color: var(--c-umber);
}

.favor-track {
  flex: 1;
  max-width: 300px;
  height: 10px;
  border: 1px solid var(--c-gold);
  background: var(--c-bamboo);
  position: relative;
  overflow: hidden;
}

.favor-fill {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  background: linear-gradient(90deg, var(--c-jade), var(--c-jade-light));
  transition: width 0.3s ease;
}

.favor-zero-mark {
  position: absolute;
  top: -1px;
  bottom: -1px;
  width: 2px;
  background: var(--c-ink);
  opacity: 0.4;
  z-index: 1;
}

.favor-value {
  font-weight: bold;
  font-size: 0.9rem;
  min-width: 28px;
  text-align: right;
}

.favor-phase {
  font-size: 0.78rem;
  color: var(--c-jade);
  border: 1px solid var(--c-jade);
  padding: 1px 6px;
  white-space: nowrap;
}

.favor-controls {
  display: flex;
  gap: 3px;
}

.favor-button {
  width: 22px;
  height: 22px;
  padding: 0;
  border: 1px solid var(--c-gold);
  background: var(--c-parchment);
  color: var(--c-ink);
  font-family: inherit;
  font-weight: bold;
  font-size: 0.9rem;
  line-height: 1;
  cursor: pointer;
  transition: all 0.15s;
}

.favor-button:hover:not(:disabled) {
  background: var(--c-jade);
  color: var(--c-cloud);
  border-color: var(--c-jade);
}

.favor-button:active:not(:disabled) {
  transform: scale(0.92);
}

.favor-button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
