
.char-layout {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.section-head {
  font-size: 0.92rem;
  font-weight: bold;
  color: var(--c-ink);
  padding-bottom: 4px;
  border-bottom: 2px solid var(--c-jade);
  display: inline-block;
  letter-spacing: 1px;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 8px;
}

.info-item {
  border: 1px solid var(--c-gold);
  padding: 8px;
  background: var(--c-cloud);
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.info-label {
  font-size: 0.72rem;
  color: var(--c-umber);
  border-bottom: 1px dashed var(--c-gold);
  padding-bottom: 2px;
}

.info-value {
  font-size: 0.85rem;
  font-weight: bold;
}

.mental-box {
  border: 1px solid var(--c-gold);
  padding: 10px 12px;
  background: var(--c-cloud);
  position: relative;
}

.mental-box::before {
  content: '「';
  position: absolute;
  top: 4px;
  left: 6px;
  font-size: 1.1rem;
  color: var(--c-jade);
  opacity: 0.6;
}

.mental-box::after {
  content: '」';
  position: absolute;
  bottom: 4px;
  right: 6px;
  font-size: 1.1rem;
  color: var(--c-jade);
  opacity: 0.6;
}

.mental-text {
  font-size: 0.82rem;
  line-height: 1.5;
  color: var(--c-ink);
  padding-left: 14px;
  font-style: italic;
}

@media (max-width: 600px) {
  .info-grid {
    grid-template-columns: 1fr;
  }
}
