
.protagonist-layout {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.section-head {
  font-size: 0.92rem;
  font-weight: bold;
  color: var(--c-ink);
  padding-bottom: 4px;
  border-bottom: 2px solid var(--c-jade);
  display: inline-block;
  letter-spacing: 1px;
}

.status-grid {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.status-item {
  border: 1px solid var(--c-gold);
  padding: 8px 10px;
  background: var(--c-cloud);
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.status-label {
  font-size: 0.72rem;
  color: var(--c-umber);
  border-bottom: 1px dashed var(--c-gold);
  padding-bottom: 2px;
}

.status-value {
  font-size: 0.85rem;
  font-weight: bold;
}

.status-value.mental {
  font-style: italic;
  font-weight: normal;
  color: var(--c-umber);
}

.inventory-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.item-row {
  display: flex;
  align-items: center;
  border: 1px solid var(--c-gold);
  padding: 7px 8px;
  background: var(--c-cloud);
  transition: transform 0.2s;
}

.item-row:hover {
  transform: translateX(4px);
  border-color: var(--c-jade);
}

.item-icon {
  width: 28px;
  height: 28px;
  background: linear-gradient(135deg, var(--c-jade), var(--c-jade-light));
  border: 1px solid var(--c-jade);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-right: 8px;
  font-weight: bold;
  font-size: 0.8rem;
  color: var(--c-cloud);
}

.item-detail {
  flex: 1;
}

.item-name {
  font-weight: bold;
  display: block;
  font-size: 0.85rem;
}

.item-desc {
  font-size: 0.74rem;
  color: var(--c-umber);
}

.item-count {
  background: var(--c-ink);
  color: var(--c-parchment);
  padding: 2px 6px;
  font-size: 0.72rem;
  font-weight: bold;
}

.empty-state {
  text-align: center;
  color: var(--c-umber);
  padding: 16px;
  font-style: italic;
  font-size: 0.85rem;
  border: 1px dashed var(--c-gold);
}
